const nativeNote =
  "Generated by scripts/generate-navigation-glyphs.mjs. Wayfinding artwork: packages/icons/src/owned/navigation-glyphs.json (Pointr Maps - Express). NavigationPointer01: packages/icons/src/pointr/icons.generated.ts (Pointr node 1007:11851). Edit sources, never this file.";
